<?php require __DIR__.'/../app/bootstrap.php';$u=require_seller();$a=application((int)$u['id']);$title=t('Store profile');$err=[];
if(post()){
 require_commerce();$pickup=val('pickup_enabled')==='yes'?1:0;$delivery=val('delivery_enabled')==='yes'?1:0;$fee=val('delivery_fee');
 if(!$pickup&&!$delivery)$err[]=t('Enable at least pickup or delivery.');
 if(!preg_match('/^\d{1,5}(\.\d{1,2})?$/',$fee))$err[]=t('Enter a delivery fee from Rs 0 to Rs 99,999.99.');
 if(!$err){db()->beginTransaction();q('UPDATE users SET full_name=full_name WHERE id=?',[$u['id']]);$exists=one('SELECT seller_id FROM seller_fulfillment WHERE seller_id=?',[$u['id']]);$params=[$pickup,$delivery,(int)round((float)$fee*100),now(),$u['id']];if($exists)q('UPDATE seller_fulfillment SET pickup_enabled=?,delivery_enabled=?,delivery_fee_paisa=?,updated_at=? WHERE seller_id=?',$params);else q('INSERT INTO seller_fulfillment (pickup_enabled,delivery_enabled,delivery_fee_paisa,updated_at,seller_id) VALUES (?,?,?,?,?)',$params);db()->commit();flash(t('Pickup and delivery settings saved.'));go('seller/store.php');}
}
$deliveryOptions=fulfillment((int)$u['id']);require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><span class="heading-kicker"><?=e(t('YOUR APPROVED BUSINESS'))?></span><h1><?=e(t('Store profile'))?></h1><p><?=e(t('These are the details approved by your administrator.'))?></p></div><section class="panel form-panel"><img class="business-logo" src="<?=e(image_url($a['logo_id']))?>" alt="<?=e(t('Business logo'))?>"><h2><?=e($a['business_name'])?></h2><span class="chip"><?=e(t('Approved seller'))?></span><dl class="details"><dt><?=e(t('Business address'))?></dt><dd><?=nl2br(e($a['address']))?></dd><dt><?=e(t('Business phone'))?></dt><dd><?=e($a['business_phone'])?></dd><dt><?=e(t('Owner'))?></dt><dd><?=e($u['full_name'])?></dd><dt><?=e(t('Approved on'))?></dt><dd><?=e(local_time($a['reviewed_at']))?></dd></dl><p class="hint"><?=e(t('Business identity changes require another review. Self-service store profile editing will be added in the next stage.'))?></p></section><?php if(commerce_ready()): ?><section class="panel form-panel space-top"><h2><?=e(t('Pickup & delivery'))?></h2><p><?=e(t('Your delivery charge is shown separately at checkout. Self pickup always has no delivery charge.'))?></p><?php errors($err); ?><form method="post"><?=csrf()?><label class="check"><input type="checkbox" name="pickup_enabled" value="yes" <?=($_SERVER['REQUEST_METHOD']==='POST'?val('pickup_enabled')==='yes':$deliveryOptions['pickup_enabled'])?'checked':''?>> <?=e(t('Self pickup available · Rs 0 delivery charges'))?></label><label class="check"><input type="checkbox" name="delivery_enabled" value="yes" <?=($_SERVER['REQUEST_METHOD']==='POST'?val('delivery_enabled')==='yes':$deliveryOptions['delivery_enabled'])?'checked':''?>> <?=e(t('Delivery available'))?></label><?php field('delivery_fee',t('Delivery charge per shop order (Rs)'),'number','required min="0" max="99999.99" step="0.01"',$_SERVER['REQUEST_METHOD']==='POST'?val('delivery_fee'):number_format($deliveryOptions['delivery_fee_paisa']/100,2,'.','')); ?><p class="hint"><?=e(t('A zero fee means free delivery when delivery is enabled. The charge applies once per order from your shop.'))?></p><button class="pill primary space-top"><?=e(t('Save Pickup & Delivery'))?></button></form></section><?php endif ?><?php require ROOT.'/app/workspace-end.php'; ?>
